<?php $u=rtrim($_ENV['APP_URL']??'','/'); $o=$offer??[]; ?>
<div class="page-head"><div><span class="eyebrow">ACADÉMICO · OFERTA</span><h1><?=htmlspecialchars($title)?></h1><p>La malla debe corresponder a la carrera seleccionada; Orion lo valida también en backend.</p></div><a href="<?=$u?>/admin/academico/oferta">Volver</a></div>
<section class="card"><form method="post" action="<?=$u?>/admin/academico/oferta/save" class="form-grid"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(\App\Core\Csrf::token())?>"><input type="hidden" name="id" value="<?=$o['id']??''?>"><label>Período<select name="periodo_academico_id" required><option value="">Seleccione</option><?php foreach($periods as $x):?><option value="<?=$x['id']?>" <?=($o['periodo_academico_id']??null)==$x['id']?'selected':''?>><?=htmlspecialchars($x['nombre'])?></option><?php endforeach;?></select></label><label>Estado<select name="estado_oferta_id" required><option value="">Seleccione</option><?php foreach($states as $x):?><option value="<?=$x['id']?>" <?=($o['estado_oferta_id']??null)==$x['id']?'selected':''?>><?=htmlspecialchars($x['nombre'])?></option><?php endforeach;?></select></label><label>Carrera<select id="carrera_id" name="carrera_id" required><option value="">Seleccione</option><?php foreach($careers as $x):?><option value="<?=$x['id']?>" <?=($o['carrera_id']??null)==$x['id']?'selected':''?>><?=htmlspecialchars($x['nombre'])?></option><?php endforeach;?></select></label><label>Malla<select id="malla_id" name="malla_id" required><option value="">Seleccione</option><?php foreach($curricula as $x):?><option data-career="<?=$x['carrera_id']?>" value="<?=$x['id']?>" <?=($o['malla_id']??null)==$x['id']?'selected':''?>><?=htmlspecialchars($x['carrera'].' · '.$x['codigo'].' · '.$x['nombre'])?></option><?php endforeach;?></select></label><label>Sede<select name="sede_id"><option value="">Todas / no especificada</option><?php foreach($campuses as $x):?><option value="<?=$x['id']?>" <?=($o['sede_id']??null)==$x['id']?'selected':''?>><?=htmlspecialchars($x['nombre'])?></option><?php endforeach;?></select></label><label>Modalidad<select name="modalidad_academica_id"><option value="">Sin especificar</option><?php foreach($modalities as $x):?><option value="<?=$x['id']?>" <?=($o['modalidad_academica_id']??null)==$x['id']?'selected':''?>><?=htmlspecialchars($x['nombre'])?></option><?php endforeach;?></select></label><label>Código<input name="codigo" required value="<?=htmlspecialchars($o['codigo']??'')?>"></label><label>Nombre<input name="nombre" required value="<?=htmlspecialchars($o['nombre']??'')?>"></label><label>Fecha publicación<input type="datetime-local" name="fecha_publicacion" value="<?=isset($o['fecha_publicacion'])&&$o['fecha_publicacion']?htmlspecialchars(str_replace(' ','T',substr($o['fecha_publicacion'],0,16))):''?>"></label><label class="check"><input type="checkbox" name="activo" value="1" <?=!isset($o['activo'])||$o['activo']?'checked':''?>> Activa</label><div><button class="btn">Guardar oferta</button></div></form></section>
<script>const c=document.getElementById('carrera_id'),m=document.getElementById('malla_id');function f(){const v=c.value;[...m.options].forEach((o,i)=>{if(i)o.hidden=!!v&&o.dataset.career!==v});if(m.selectedOptions[0]?.hidden)m.value=''}c.addEventListener('change',f);f();</script>
